            ri = routes[i]
            if not ri:
                continue
            li = loads[i]
            cost_from_old = route_cost(ri)
            for pos in range(len(ri)):
                node = ri[pos]
                new_from = ri[:pos] + ri[pos + 1 :]
                cost_from_new = route_cost(new_from)

                cand_routes = set()
                for u in nearest.get(node, []):
                    if u in where:
                        cand_routes.add(where[u])
                cand_routes.add(i)
                cand_routes = [j for j in cand_routes if j != i and routes[j]]
                cand_routes.sort()

                for j in cand_routes:
                    ins = best_insertion_into_route(node, j, routes[j])
                    if ins is None:
                        continue
                    cost_to_old = route_cost(routes[j])
                    cost_to_new, new_to = ins
                    delta = (cost_from_new + cost_to_new) - (cost_from_old + cost_to_old)
                    if best_global is None or delta < best_global[0]:
                        best_global = (delta, i, pos, j, new_from, new_to)

        if best_global is None:
            return False

        delta, i, pos, j, new_from, new_to = best_global
        if delta >= 0:
            if hint is not None and hint > 0 and len(routes) > hint + 1:
                pass
            else:
                return False

        routes[i] = new_from
        routes[j] = new_to
        if not routes[i]:
            routes.pop(i)
        return True

    for _ in range(40):
        if len(routes) <= 1:
            break
        if not inter_relocate(routes):
            break

    # targeted edit 4: inter-route swap of single customers (limited candidates, exact cost)
    def inter_swap(routes):
        n = len(routes)
        if n <= 1:
            return False

        loads = [route_load(r) for r in routes]

        cust_list = list(instance["customer_ids"])
        topk = 5
        nearest = {}
        for v in cust_list:
            dv = []
            row_v = matrix[v]
            for u in cust_list:
                if u == v:
                    continue
                dv.append((row_v[u], u))
            dv.sort(key=lambda x: (x[0], x[1]))
            nearest[v] = [u for _, u in dv[:topk]]

        where = {}
        for i in range(n):
            for v in routes[i]:
                where[v] = i

        best = None  # (delta, i, pi, j, pj)

        # limit scanning: only consider route pairs involving nearby customers of first route nodes
        for i in range(n):
            ri = routes[i]
            if not ri:
                continue
            base_cost_i = route_cost(ri)
            for pi, a in enumerate(ri):
                for u in nearest.get(a, []):
                    if u in where:
                        j = where[u]
                        if j == i or not routes[j]:
                            continue
                        rj = routes[j]
                        base_cost_j = route_cost(rj)
                        # locate u position(s)
                        # since routes are lists, scan positions; deterministically take all positions of that u (usually 1)
                        for pj, b in enumerate(rj):
                            if b != u:
                                continue
                            li_new_i = loads[i] - demands[a] + demands[b]
                            li_new_j = loads[j] - demands[b] + demands[a]
                            if li_new_i > capacity or li_new_j > capacity:
                                continue
                            new_ri = ri[:]
                            new_ri[pi] = b
                            new_rj = rj[:]
                            new_rj[pj] = a
                            if not new_ri or not new_rj:
                                continue
                            new_cost = route_cost(new_ri) + route_cost(new_rj)
                            delta = new_cost - (base_cost_i + base_cost_j)
                            if best is None or delta < best[0]:
                                best = (delta, i, pi, j, pj)
        if best is None:
            return False

        delta, i, pi, j, pj = best
        if delta >= 0:
            if hint is not None and hint > 0 and len(routes) > hint + 1:
                pass
            else:
                return False

        a = routes[i][pi]
        b = routes[j][pj]
        routes[i][pi] = b
        routes[j][pj] = a
        return True

    # apply a few improving swaps then 2-opt again on affected routes
    for _ in range(20):
        if len(routes) <= 1:
            break
        if not inter_swap(routes):
            break
        for idx in range(len(routes)):
            if len(routes[idx]) >= 4:
                routes[idx] = two_opt_improve(routes[idx])

    routes = [r for r in routes if r]
    return routes
